// 侧边栏电子钟（完整版：IP定位 + 天气 + 湿度 + 温度）
(function () {
  function pad(n) { return n > 9 ? n : '0' + n; }
  var week = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];

  function renderClock(ip, city, weather, temp, humidity) {
    var box = document.getElementById('hexo_electric_clock');
    if (!box) return;
    var cd = new Date();
    var h = cd.getHours();
    var str = h > 12 ? ' PM' : ' AM';
    var time = pad(h) + ':' + pad(cd.getMinutes()) + ':' + pad(cd.getSeconds());
    var date = cd.getFullYear() + '-' + pad(cd.getMonth() + 1) + '-' + pad(cd.getDate()) + ' ' + week[cd.getDay()];

    var weatherHtml = weather ? ' ' + weather : '';
    var tempHtml = temp ? ' ' + temp + '°C' : '';
    var humHtml = humidity ? ' 💧' + humidity + '%' : '';
    var ipHtml = ip ? ' ' + ip : '';
    var cityHtml = city ? ' ' + city : '';

    box.innerHTML =
      '<div class="clock-row">' +
      '<span class="card-clock-clockdate">' + date + '</span>' +
      '<span class="card-clock-weather">' + weatherHtml + tempHtml + '</span>' +
      '<span class="card-clock-humidity">' + humHtml + '</span>' +
      '</div>' +
      '<div class="clock-row">' +
      '<span class="card-clock-time">' + time + '</span>' +
      '</div>' +
      '<div class="clock-row">' +
      '<span class="card-clock-ip">' + ipHtml + '</span>' +
      '<span class="card-clock-location">' + cityHtml + '</span>' +
      '<span class="card-clock-dackorlight">' + str + '</span>' +
      '</div>';

    var loading = document.getElementById('card-clock-loading');
    if (loading) loading.innerHTML = '';
  }

  function updateTime() {
    var box = document.getElementById('hexo_electric_clock');
    if (!box) return;
    var cd = new Date();
    var h = cd.getHours();
    var str = h > 12 ? ' PM' : ' AM';
    var time = pad(h) + ':' + pad(cd.getMinutes()) + ':' + pad(cd.getSeconds());
    var timeEl = box.querySelector('.card-clock-time');
    if (timeEl) timeEl.innerHTML = time;
    var dlEl = box.querySelector('.card-clock-dackorlight');
    if (dlEl) dlEl.innerHTML = str;
  }

  function init() {
    // 先渲染基础时钟（无天气），保证不白屏
    renderClock('', '', '', '', '');
    setInterval(updateTime, 1000);

    // 尝试获取 IP 和天气
    try {
      if (typeof returnCitySN !== 'undefined') {
        var cip = returnCitySN['cip'] || '';
        var cname = returnCitySN['cname'] || '';
        // 用 wttr.in 获取天气（支持中国城市拼音）
        var cityQuery = cname || 'Nantong';
        fetch('https://wttr.in/' + encodeURIComponent(cityQuery) + '?format=j1&lang=zh')
          .then(function (r) { return r.json(); })
          .then(function (data) {
            var cur = data.current_condition[0];
            var weather = cur.lang_zh ? cur.lang_zh[0].value : (cur.weatherDesc ? cur.weatherDesc[0].value : '');
            var temp = cur.temp_C;
            var humidity = cur.humidity;
            renderClock(cip, cname, weather, temp, humidity);
          })
          .catch(function () {
            // 天气获取失败，只显示 IP 和城市
            renderClock(cip, cname, '', '', '');
          });
      }
    } catch (e) {
      // 静默失败，时钟已在渲染
    }
  }

  if (document.readyState !== 'loading') init();
  else document.addEventListener('DOMContentLoaded', init);
  document.addEventListener('pjax:complete', function () { setTimeout(init, 500); });
})();
